export type LivePluralMessageKey = "filterResults" | "vessels" | "needsAttention" | "invocationFailedCount" | "invocationRunningCount" | "dependenciesIn" | "dependenciesOut" | "commentsCount" | "messages" | "additionalGitWarningsHidden";
export type LiveMessageKey = Exclude<keyof typeof liveMessages.en, LivePluralMessageKey>;

export const translateLiveMessage = (
  locale: DashboardLocale,
  key: LiveMessageKey,
  variables?: DashboardMessageVariables,
): string => translateDashboardMessage(liveMessages, locale, key, variables);

export const translateLivePlural = (
  locale: DashboardLocale,
  key: LivePluralMessageKey,
  count: number,
  variables?: DashboardMessageVariables,
): string => translateDashboardPlural(liveMessages, locale, key, count, variables);

export const useLiveI18n = () => {
  const context = useOptionalDashboardI18n();
  const locale = context?.locale ?? DEFAULT_DASHBOARD_LOCALE;
  const fallbackFormatters = useMemo(() => createDashboardFormatters(locale), [locale]);
  const t = useCallback((key: LiveMessageKey, variables?: DashboardMessageVariables): string => (
    translateLiveMessage(locale, key, variables)
  ), [locale]);
  const tp = useCallback((key: LivePluralMessageKey, count: number, variables?: DashboardMessageVariables): string => (
    translateLivePlural(locale, key, count, variables)
  ), [locale]);
  return {
    locale,
    t,
    tp,
    formatNumber: context?.formatNumber ?? fallbackFormatters.formatNumber,
    formatDate: context?.formatDate ?? fallbackFormatters.formatDate,
    formatTime: context?.formatTime ?? fallbackFormatters.formatTime,
    formatRelativeTime: context?.formatRelativeTime ?? fallbackFormatters.formatRelativeTime,
    formatList: context?.formatList ?? fallbackFormatters.formatList,
  };
};
